        @foreach($validation['topology'] ?? [] as $network)<details><summary>Transformer #{{ $network['transformer_id'] }}: {{ count($network['nodes'] ?? []) }} connected nodes / {{ count($network['sections'] ?? []) }} surveyed sections</summary><div class="table-wrap"><table class="table mdb-review-table"><thead><tr><th>Section</th><th>Surveyed waypoint pair</th><th>Endpoint / geometry estimate (m)</th><th>Used length (m)</th></tr></thead><tbody>@foreach($network['sections'] ?? [] as $edge)<tr><td><a href="{{ route('mdb-workflow.show', [$batch, 'transformer_id'=>$network['transformer_id']]) }}#section-{{ $edge['section_id'] }}">#{{ $edge['section_id'] }}</a></td><td>Waypoint #{{ $edge['start_waypoint_id'] }} &rarr; #{{ $edge['end_waypoint_id'] }}</td><td>{{ isset($edge['estimated_length_m']) ? number_format($edge['estimated_length_m'], 2) : 'Unresolved' }}</td><td>{{ isset($edge['length_m']) ? number_format($edge['length_m'], 2) : 'Unresolved' }}<small>{{ str($edge['length_kind'])->replace('_', ' ')->title() }}</small></td></tr>@endforeach</tbody></table></div></details>@endforeach
    </section>
    <section class="card" id="review"><h2>Submission and verifier decisions</h2><p class="mdb-note">Every decision identifies its data revision. Editing approved values invalidates approval and supersedes the earlier exports.</p>
