        @can('mdb-workflow.edit')@if(in_array($batch->status, ['draft','submitted','returned'], true))<form method="POST" action="{{ route('mdb-workflow.transition', $batch) }}">@csrf<input type="hidden" name="revision" value="{{ $batch->revision }}"><input type="hidden" name="action" value="review"><div class="mdb-fields"><label class="mdb-span-all">Data entry completion comment<textarea name="comment" maxlength="4000" rows="2"></textarea></label></div><div class="mdb-form-actions"><button class="btn btn-primary">Send entered network for verification</button></div></form>@endif @endcan
        @can('mdb-workflow.verify')<div class="mdb-decision"><form method="POST" action="{{ route('mdb-workflow.transition', $batch) }}">@csrf<input type="hidden" name="revision" value="{{ $batch->revision }}"><div class="mdb-fields"><label class="mdb-span-all">Verifier comment / rejection reason<textarea name="comment" required minlength="5" maxlength="4000" rows="3"></textarea></label></div><div class="mdb-form-actions"><button class="btn btn-light" name="action" value="comment">Record review comment</button>@if($batch->status === 'awaiting_verification')<button class="btn btn-danger" name="action" value="reject">Return for correction</button><button class="btn btn-success" name="action" value="approve" @disabled(!($validation['valid'] ?? false))>Approve current revision</button>@endif</div>@if(!($validation['valid'] ?? false))<small>Resolve the critical validation errors before final approval.</small>@endif</form></div>@endcan
        @forelse($batch->decisions->sortByDesc('created_at') as $decision)<article class="mdb-decision"><strong>{{ str($decision->decision)->replace('_', ' ')->title() }}</strong> &middot; Revision #{{ $decision->revision?->number }} &middot; {{ $decision->verifier?->name ?? 'Workflow user' }}<small>{{ $decision->created_at?->timezone('Asia/Karachi')->format('d M Y H:i') }} PKT</small><p>{{ $decision->comments }}</p></article>@empty<p class="mdb-note">No submission or verifier decisions have been recorded.</p>@endforelse
