        @can('mdb-workflow.export')<form method="POST" action="{{ route('mdb-workflow.exports.store', $batch) }}">@csrf<input type="hidden" name="revision" value="{{ $batch->revision }}"><div class="mdb-fields"><label>Export scope<select name="transformer_id"><option value="">Consolidated feeder (requires compatible mapping)</option>@foreach($batch->transformers as $transformer)<option value="{{ $transformer->id }}" @selected($selectedTransformer?->id === $transformer->id)>{{ $transformer->code }}</option>@endforeach</select></label><label>Template bound to approved revision<input value="{{ data_get($batch->approvedRevision?->snapshot, 'template.code', 'Approval required') }} v{{ data_get($batch->approvedRevision?->snapshot, 'template.version', '') }}" readonly><input type="hidden" name="template_id" value="{{ data_get($batch->approvedRevision?->snapshot, 'template.id', '') }}"><small>Changing the template requires renewed approval.</small></label></div><div class="mdb-form-actions"><button class="btn btn-primary" @disabled(!$batch->approved_revision_id)>Queue MDB export</button>@if(!$batch->approved_revision_id)<small>Final approval of this immutable revision is required.</small>@endif</div></form>@endcan
        @forelse($batch->exports->sortByDesc('created_at') as $export)<article class="row-card"><div class="row-card-head"><strong>Export #{{ $export->id }} &middot; {{ $export->transformer?->code ?? 'Consolidated feeder' }}</strong><span class="status mdb-status-{{ $export->status }}">{{ str($export->status)->replace('_', ' ')->title() }}</span></div><p class="mdb-note">Data revision #{{ $export->revision?->number }} &middot; Template {{ $export->template?->version ?? $export->template_version }} &middot; Mapping {{ $export->mapping_version }} &middot; Attempts {{ $export->attempts }} @if($export->generated_at)&middot; Generated {{ $export->generated_at->timezone('Asia/Karachi')->format('d M Y H:i') }} PKT @endif</p>
            @if($export->superseded_at)<p class="mdb-inline-error">Superseded: the source data or engineering configuration changed. Use an export from the latest approved revision.</p>@endif
            <div class="actions">@if($export->status === 'generated' && !$export->superseded_at)@can('mdb-workflow.export')<a class="btn btn-light" href="{{ route('mdb-workflow.exports.download', $export) }}">Download verified MDB</a>@endcan @endif
            @if(in_array($export->status, ['failed','worker_not_configured'], true) && !$export->superseded_at)@can('mdb-workflow.export')<form method="POST" action="{{ route('mdb-workflow.exports.retry', $export) }}">@csrf<button class="btn btn-sm btn-light">Retry export job</button></form>@endcan @endif</div>
            @if($export->output_sha256)<small class="mdb-code">Output SHA-256 {{ $export->output_sha256 }}</small>@endif
            @if($export->log)<details><summary>Exporter log and readback</summary><pre class="mdb-code">{{ $export->log }}</pre><pre class="mdb-code">{{ json_encode($export->readback, JSON_PRETTY_PRINT | JSON_UNESCAPED_SLASHES) }}</pre></details>@endif
            @php
                $events = $export->validations->sortBy('id');
                $lastReturnedId = $events->where('status', 'returned')->last()?->id ?? 0;
                $checks = $events->where('id', '>', $lastReturnedId)->pluck('status')->all();
            @endphp
            <p class="mdb-note"><strong>Current analysis status:</strong> {{ $events->last() ? str($events->last()->status)->replace('_', ' ')->title() : 'Pending analysis in SynerGEE' }}.</p>
            <ul class="mdb-state-list">@foreach(['downloaded'=>'Downloaded','opened'=>'Opened in SynerGEE','connectivity_checked'=>'Connectivity checked','load_flow_checked'=>'Load flow checked','accepted'=>'Accepted'] as $status=>$label)<li data-complete="{{ in_array($status, $checks, true) ? 'true' : 'false' }}">{{ $label }}</li>@endforeach</ul>
            @foreach($export->validations->sortBy('created_at') as $check)<p class="mdb-note"><strong>{{ str($check->status)->replace('_', ' ')->title() }}</strong> &middot; {{ $check->analyst?->name }} &middot; {{ $check->created_at?->timezone('Asia/Karachi')->format('d M Y H:i') }} PKT @if($check->synergee_version)&middot; SynerGEE {{ $check->synergee_version }}@endif<br>{{ $check->comments }}</p>@endforeach
            @can('mdb-workflow.analyze')@if($export->status === 'generated' && !$export->superseded_at)<details><summary>Record SynerGEE validation result</summary><form method="POST" action="{{ route('mdb-workflow.analysis.store', $export) }}">@csrf<div class="mdb-fields"><label>Completed analysis step<select name="status" required>@foreach(['downloaded'=>'Downloaded','opened'=>'Opened successfully in SynerGEE','connectivity_checked'=>'Connectivity checked','load_flow_checked'=>'Load flow checked','accepted'=>'Accepted','returned'=>'Returned for correction'] as $status=>$label)<option value="{{ $status }}">{{ $label }}</option>@endforeach</select></label><label>SynerGEE version<input name="synergee_version" maxlength="60"></label><label class="mdb-span-all">Results / correction comments<textarea name="comments" required maxlength="4000" rows="3"></textarea></label><label class="mdb-span-all">Evidence reference<input name="evidence[reference]" maxlength="2000" placeholder="Report, test case, or authorized document reference"></label></div><div class="mdb-form-actions"><button class="btn btn-primary">Record analysis step</button><small>Acceptance requires the preceding checks to be recorded.</small></div></form></details>@endif @endcan
        </article>@empty<p class="empty">No export jobs created. MDB output counts appear separately from transformer record counts.</p>@endforelse
